param([switch]$RunMockTests,[switch]$AdapterMocksVerified,[string]$MockRunner=(Join-Path $PSScriptRoot '../.tools/luau/luau.exe'))
$ErrorActionPreference='Stop'
$taskRoot=Split-Path -Parent $PSScriptRoot
$utf8=[Text.UTF8Encoding]::new($false)
$catalogPath=Join-Path $taskRoot 'docs/results/executor-catalog-v3.json'
$catalog=Get-Content -LiteralPath $catalogPath -Raw|ConvertFrom-Json
if(-not $catalog.complete_normalization -or $catalog.accepted_entries -ne $catalog.entries.Count){throw 'Executor compatibility inventory requires a complete normalized catalog.'}
$mockStatus='not_run_by_this_generation; source-defined contracts, release gate runs the harness'
$mockDate=$null
$mockEvidence=$null
if($RunMockTests -and $AdapterMocksVerified){throw 'Choose actual test execution or an already-successful mandatory-gate command, not both.'}
if($RunMockTests -or $AdapterMocksVerified){
    $MockRunner=(Resolve-Path -LiteralPath $MockRunner).Path
    $runnerHash=(Get-FileHash -LiteralPath $MockRunner -Algorithm SHA256).Hash.ToLowerInvariant()
    $runnerLock=Get-Content -LiteralPath (Join-Path $taskRoot 'upstream.lock.json') -Raw|ConvertFrom-Json
    if($runnerHash -cne $runnerLock.windows_interpreter_sha256){throw 'Adapter mock runner does not match the pinned official interpreter.'}
}
if($RunMockTests){
    & $MockRunner (Join-Path $taskRoot 'adapter/test-v3.luau')
    if($LASTEXITCODE -ne 0){throw 'Injected adapter contract regression failed.'}
}
if($RunMockTests -or $AdapterMocksVerified){
    $mockStatus='passed_injected_host_harness';$mockDate=[DateTime]::UtcNow.ToString('o')
    $mockEvidence=[ordered]@{command=('"'+$MockRunner+'" "adapter/test-v3.luau"');exit_code=0;runner_sha256=$runnerHash;runner_revision=$runnerLock.revision;source_sha256=(Get-FileHash -LiteralPath (Join-Path $taskRoot 'adapter/test-v3.luau') -Algorithm SHA256).Hash.ToLowerInvariant();adapter_sha256=(Get-FileHash -LiteralPath (Join-Path $taskRoot 'adapter/decompile.luau') -Algorithm SHA256).Hash.ToLowerInvariant();verification=$(if($RunMockTests){'executed by this generator'}else{'mandatory validate.ps1 invokes generator only after checking successful command exit'})}
}
$rows=@(foreach($entry in $catalog.entries){
    [ordered]@{
        id=$entry.id;name=$entry.name;kind=$entry.kind;platform=$entry.platform
        architecture=[ordered]@{advertised=$entry.architecture;actual=$null;status='unknown; not measured'}
        builds=[ordered]@{advertised_executor=$entry.advertised_executor_version;advertised_roblox=$entry.advertised_roblox_build;actual_executor=$null;actual_roblox=$null;actual_evidence=$null}
        capabilities=[ordered]@{status='not_probed';script_instance_targets='not_probed';raw_bytecode_targets='not_probed';function_targets='not_probed';script_getter=$null;function_getter=$null;binary_string_handling='not_probed';request_api=$null;transport_behavior='not_probed';representation_normalization='not_probed'}
        native_api=[ordered]@{options_status='unknown';supported_options=@();unsupported_options=@();return_values='unknown';error_behavior='unknown';custom_timeout_contract='unverified'}
        bytecode=[ordered]@{representation='unverified';encoding='unverified';profile='unverified';instruction_features='unverified';transformation='unverified'}
        coverage=[ordered]@{distinct_known_source_native_programs_verified=0;distinct_native_models_verified=0;distinct_supplied_bytecode_programs_verified=0;runtime_inputs=0;typed_observations=0;timing_repetitions=0;normal_engine_known_source_programs=0}
        observation=[ordered]@{catalog_observed_at_utc=$catalog.observed_at_utc;catalog_updated_at=$entry.catalog_updated_at;independent_test_date_utc=$null;source='WEAO advertised metadata only';website=$entry.website;advertised_builtin_decompiler=$entry.advertised_builtin_decompiler}
        status=$(if($entry.kind -eq 'external_tool'){'catalog_only; required interfaces not established'}else{'catalog_only; adapter compatibility not run'})
        limitations=@($entry.limitations)+@('No architecture, native option, getter, representation, packet-format or complete adapter-to-service contract has been independently verified for this advertised build.','Catalog metadata, built-in decompilation advertising, UNC/sUNC scores and successful handshakes are not native end-to-end evidence.')
    }
})
$contracts=@(
    @{id='volt';name='Volt';url='https://docs.volt.rs/docs/scripts/decompile';targets=@('script_instance','raw_bytecode_string');function='native entry rejects; explicit capability-based canonical helper is separate';options='documented native table, explicitly supported subset only'},
    @{id='lynx';name='Lynx';url='https://getlynx.gg/docs/api/scripts';targets=@('script_instance','raw_bytecode_string','function_when_getter_available');function='mock routing only; no native function-dump verification';options='documented native table, explicitly supported subset only'},
    @{id='madium';name='Madium';url=$null;targets=@('script_instance');function='native entry rejects; explicit canonical helpers are extensions';options='no native second argument; explicit canonical helper options are separate'}
)
$mockRows=@(foreach($contract in $contracts){
    $wrapper=Join-Path $taskRoot ('adapter/executors/'+$contract.id+'.luau')
    [ordered]@{id=('mock-contract:'+ $contract.id);name=$contract.name;evidence_kind='injected_host_contract; not an executor runtime';platform='host Luau on Windows';architecture='executor architecture unknown';actual_executor_build=$null;actual_roblox_build=$null;catalog_row_inheritance='none';documented_source=$contract.url;target_contract=$contract.targets;function_contract=$contract.function;native_options_contract=$contract.options;supported_option_families=$(if($contract.id -eq 'madium'){@()}else{@('debug/descriptive binding names','local function presentation','recoverable type hints','blank lines','indentation','line width','implemented call/table layouts')});unsupported_options='explicit errors; full advertised option set is not claimed';returns='source string on success; detailed canonical helpers retain full response';errors='injected tests cover original getter-payload identity, unsupported options, and structured failed-quality source retention';custom_timeout='installation configuration or decompile_with_timeout(target, canonical_options, seconds); numeric native argument two rejects';encoding='binary-string base64 transport is mocked; no executor encoding/profile established';bytecode_profile='unverified by these mocks';distinct_known_source_native_programs_verified=0;distinct_supplied_bytecode_programs_verified=0;test_status=$mockStatus;tested_at_utc=$mockDate;wrapper_sha256=(Get-FileHash -LiteralPath $wrapper -Algorithm SHA256).Hash.ToLowerInvariant();harness_sha256=(Get-FileHash -LiteralPath (Join-Path $taskRoot 'adapter/test-v3.luau') -Algorithm SHA256).Hash.ToLowerInvariant();limitations=@('Synthetic getter/request responses are injected; the mock packet is not counted as a reconstructed source program.','Fixed-parameter entry packets currently reject; live external upvalue values are absent from serialized bytecode.','These rows do not promote any advertised catalog build to native compatibility.')}
})
$historicalPath=Join-Path $taskRoot 'docs/results/madium-live.json'
$historical=Get-Content -LiteralPath $historicalPath -Raw|ConvertFrom-Json
$legacy=[ordered]@{id='historical-v0.2-madium-windows';evidence_kind='historical live client; independent of v0.3 and current catalog build';decompiler_version='0.2.0';executor='Madium';actual_executor_build=$historical.executor[1];actual_roblox_build=$historical.runtime;platform='windows';architecture='not recorded independently';profile='luau-v14';encoding='roblox_opcode227';representation='47-byte processed native packet plus separately supplied official-compiler packets';native_options_support='not established; historical adapter contract predates v0.3 repair';capabilities=[ordered]@{script_getter='native extraction recorded for one packet; exact getter symbol not asserted here';raw_supplied_bytecode='four separately supplied compiler fixtures';function_dump='not verified';transport='authenticated localhost HTTP, base64';restoration='raw and out-of-order restoration recorded'};coverage=[ordered]@{distinct_known_source_native_programs_verified=0;distinct_native_models_verified=1;native_model_original_source='unknown; bytewise normalized match to independent return-empty-table compiler model';distinct_supplied_bytecode_programs_verified=4;supplied_runtime_observations=20;native_model_observations=65;total_typed_observations=$historical.verified_typed_comparisons;cold_timing_runs=1;warm_timing_repetitions=$historical.latency_repetitions};observed_at_utc=$historical.verified_at;service_executable_sha256=$historical.service_binary_sha256;binary_provenance_limit=$historical.service_binary_evidence;report_path='docs/results/madium-live.json';report_sha256=(Get-FileHash -LiteralPath $historicalPath -Algorithm SHA256).Hash.ToLowerInvariant();status='historical limited model/supplied-fixture integration; not v0.3 certification';limitations=@('One unknown-source native model and repeated observations do not establish broad native program extraction.','Catalog advertised Madium build differs; no evidence transfers to Madius.','No known-source normal-engine controlled-place suite was run.','Historical timing is not a v0.3 performance result.')}
$report=[ordered]@{schema=1;version='0.3.0';generated_at_utc=[DateTime]::UtcNow.ToString('o');catalog_observed_at_utc=$catalog.observed_at_utc;catalog_source=$catalog.source_url;catalog_user_agent=$catalog.required_user_agent;catalog_raw_sha256=$catalog.raw_sha256;catalog_normalized_sha256=(Get-FileHash -LiteralPath $catalogPath -Algorithm SHA256).Hash.ToLowerInvariant();catalog_rows=$rows;catalog_counts=@{total=$rows.Count;executors=@($rows|Where-Object kind -eq 'executor').Count;external_tools=@($rows|Where-Object kind -eq 'external_tool').Count};mock_execution_evidence=$mockEvidence;mock_contract_rows=$mockRows;historical_live_rows=@($legacy);v0_3_live_rows=@();v0_3_native_status='not_run; test client reconnect pending, controlled place has no connected Studio/published environment';platform_status=@{windows='Rust/library/service/host harness available; executor evidence must retain exact row provenance';macos='not_run; user confirmed no Mac runner';android='not_run; no same-device service or paired authenticated encrypted companion';ios='not_run; no same-device service or paired authenticated encrypted companion'};evidence_boundary='Catalog, mock, historical live and current live rows are separate. No row inherits test results from another executor build, platform, evidence kind or decompiler version.';generator_sha256=(Get-FileHash -LiteralPath $PSCommandPath -Algorithm SHA256).Hash.ToLowerInvariant()}
$currentPath=Join-Path $taskRoot 'docs/results/madium-live-v3.json'
if(Test-Path -LiteralPath $currentPath){
    $current=Get-Content -LiteralPath $currentPath -Raw|ConvertFrom-Json
    $report.v0_3_native_status=$current.status
    $report.v0_3_live_rows=@([ordered]@{id='v0.3-madium-windows-transport-attempt';evidence_kind='actual failed live attempt; separate from mocks and historical success';decompiler_version='0.3.0';executor=$current.executor[0];actual_executor_build=$current.executor[1];actual_roblox_build=$current.runtime;platform=$current.platform;architecture=$current.executor_architecture;client_pid_operator_record=$current.client_pid_operator_record;service_executable_sha256=$current.service_binary_sha256;observed_at_utc=$current.host_probe.observed_at_utc;recorded_at_utc=$current.recorded_at_utc;profile='luau-v14 host decoder/compiler-model proof only';encoding='opcode227 exact native packet; adapter transport not completed';representation='47-byte exact getter packet; no container/encoding guesses';capabilities=@{getter='exact SocketTypes guard passed';native_api='four argument/target rejections passed';request='callable but bounded probes did not complete';http_service='RequestAsync blocked in observed MCP context';adapter_handshake='not completed';host_capabilities='authenticated host probe200, separate from executor path'};options_support='Madium numeric/options/raw/function rejections observed; canonical settings behavior not reached';returns='no source returned; native success return contract unverified';errors='adapter deadline captured; malformed-bytecode HTTP test not reached';coverage=@{distinct_known_source_native_programs_verified=0;distinct_unknown_source_native_models_behaviorally_verified=0;distinct_supplied_bytecode_programs_verified=0;typed_observations=0;successful_timing_samples=0;planned_supplied_programs=4};status=$current.status;cause='unknown; outside-sandbox host service had same transport failure';report_path='docs/results/madium-live-v3.json';report_sha256=(Get-FileHash -LiteralPath $currentPath -Algorithm SHA256).Hash.ToLowerInvariant();limitations=$current.limitations})
    $report.platform_status.windows='Rust/library/service/host harness available; current Madium adapter transport attempt failed, cause unknown'
}
[IO.File]::WriteAllText((Join-Path $taskRoot 'docs/results/executor-compatibility-v3.json'),($report|ConvertTo-Json -Depth 15),$utf8)
Write-Output ('Full executor matrix: '+$rows.Count+' catalog rows, '+$mockRows.Count+' separate mocked contracts, one separate historical live row; v0.3 status: '+$report.v0_3_native_status)
